+                            WnIcons.copy,
+                            size: 16.w,
+                            color: iconColor,
+                          ),
+                        ),
+                      ),
+                    ),
+                  ),
+                ),
+              ),
+              SingleChildScrollView(
+                scrollDirection: Axis.horizontal,
+                child: Padding(
+                  padding: EdgeInsets.fromLTRB(12.w, 10.h, 12.w, 12.h),
+                  child: Text(
+                    code,
