+}
+
+class _TokenMatch {
+  const _TokenMatch({required this.start, required this.end});
+
+  final int start;
+  final int end;
+}
+
+class _HighlightRange {
+  const _HighlightRange({required this.start, required this.end});
+
+  final int start;
+  final int end;
+}
+
+enum _ContentRunType { text, inlineCode, codeBlock }
+
+class _ContentRun {
+  const _ContentRun({
