+  final String? code;
+
+  bool get isText => spans != null;
+  bool get isCodeBlock => code != null;
+}
+
+class _FencedCodeMatch {
+  const _FencedCodeMatch({required this.text, required this.end});
+
+  final String text;
+  final int end;
+}
+
+_SpanState _buildSpanState({
