+    final inlineText = content.substring(markerStart + 1, markerEnd);
+    if (inlineText.contains('\n')) {
+      runs.add(
+        _ContentRun(
+          text: content.substring(markerStart, markerStart + 1),
+          type: _ContentRunType.text,
+          start: markerStart,
+          end: markerStart + 1,
+        ),
+      );
+      cursor = markerStart + 1;
+      continue;
+    }
+
+    runs.add(
+      _ContentRun(
